package httpapi

import (
	"net/http"
	"strconv"
	"time"

	"github.com/google/uuid"
	"github.com/labstack/echo/v5"

	"github.com/AnoRebel/tdc/server/internal/search"
)

// searchResult is one message that matched.
type searchResult struct {
	EventID string `json:"eventId"`
	RoomID  string `json:"roomId"`
	Sender  string `json:"sender"`
	Body    string `json:"body"`
	// Highlighted carries <mark> around the matched terms, so a client can
	// show why a result matched. It is generated by Postgres from the stored
	// text, not from anything a searcher supplied, so the only markup in it is
	// the marks themselves.
	Highlighted string `json:"highlighted"`
	SentAt      string `json:"sentAt"`
}

/*
handleSearch finds messages the caller may read.

A GET, unlike the link-preview endpoint: a search term is the caller's own
words about their own conversations, and putting it in the query string makes
a search shareable and bookmarkable. A link somebody was sent is different —
that is somebody else's URL, and it stays out of logs.
*/
func (s *Server) handleSearch(c *echo.Context) error {
	user, _ := currentUser(c)
	ctx := c.Request().Context()

	if s.search == nil {
		return echo.NewHTTPError(http.StatusServiceUnavailable, "search is not available")
	}

	query := search.Query{
		Text: c.QueryParam("q"),
		// Prefix matching for search-as-you-type, which needs trigrams rather
		// than full-text: "mkut" matches nothing in a tsquery however many
		// messages contain "mkutano".
		Prefix: c.QueryParam("prefix") == "true",
	}

	if raw := c.QueryParam("room"); raw != "" {
		roomID, err := uuid.Parse(raw)
		if err != nil {
			return echo.NewHTTPError(http.StatusBadRequest, "that is not a room")
		}
		query.Room = &roomID
	}

	if raw := c.QueryParam("limit"); raw != "" {
		if limit, err := strconv.Atoi(raw); err == nil {
			query.Limit = limit
		}
	}

	// No membership check here, deliberately. The query joins on membership,
	// so a room the caller is not in contributes nothing — checking again
	// beforehand would be a second place for the rule to be written and a
	// second place for it to be wrong.
	results, err := s.search.Search(ctx, user.ID, query)
	if err != nil {
		return err
	}

	response := make([]searchResult, 0, len(results))
	for _, result := range results {
		response = append(response, searchResult{
			EventID:     result.EventID,
			RoomID:      result.RoomID.String(),
			Sender:      result.Sender,
			Body:        result.Body,
			Highlighted: result.Highlighted,
			SentAt:      time.UnixMilli(result.SentAt).UTC().Format(time.RFC3339),
		})
	}

	return c.JSON(http.StatusOK, response)
}
